#include <stdio.h>

int main() {
    int values[] = {50, 40, 10, 9, 5, 4, 1};
    const char *symbols[] = {"L", "XL", "X", "IX", "V", "IV", "I"};
    int n = 58;
    for (int i = 0; i < 7; i++) {
        while (n >= values[i]) {
            printf("%s", symbols[i]);
            n -= values[i];
        }
    }
    printf("\n");
    return 0;
}
